INSERT INTO question_versions (id, question_id, version_number, stem, options, answer_spec, schema_version, explanation, status) VALUES
    ('2d000000-0000-4000-8000-040000000101', '2d000000-0000-4000-8000-030000000101', 1, 'Foxes became a common sight in suburban gardens from the 1980s.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"TRUE"}'::jsonb, 1, 'Paragraph A: since the 1980s foxes have become a familiar sight.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000102', '2d000000-0000-4000-8000-030000000102', 1, 'Urban foxes eat only food thrown away by people.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"FALSE"}'::jsonb, 1, 'Paragraph B: their diet ranges from earthworms to scraps.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000103', '2d000000-0000-4000-8000-030000000103', 1, 'Foxes in towns are more likely to carry disease than those in the countryside.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'The passage says nothing about disease.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000104', '2d000000-0000-4000-8000-030000000104', 1, 'Most urban foxes live in small ______ groups.', NULL, '{"type":"FILL","accepted":["family"]}'::jsonb, 1, 'Paragraph A: most live in small family groups.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000105', '2d000000-0000-4000-8000-030000000105', 1, 'Foxes shelter under garden ______.', NULL, '{"type":"FILL","accepted":["sheds"]}'::jsonb, 1, 'Paragraph B: they shelter under garden sheds.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000106', '2d000000-0000-4000-8000-030000000106', 1, 'Several councils publish ______ advising householders how to keep food waste out of reach.', NULL, '{"type":"FILL","accepted":["leaflets"]}'::jsonb, 1, 'Paragraph C: councils publish leaflets.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000107', '2d000000-0000-4000-8000-030000000107', 1, 'a reason why foxes survive better than some other mammals', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph B: the flexible diet is the main reason they thrive.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000108', '2d000000-0000-4000-8000-030000000108', 1, 'a finding about how far town foxes travel at night', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"D"}'::jsonb, 1, 'Paragraph D: less than two kilometres in a night.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000109', '2d000000-0000-4000-8000-030000000109', 1, 'How much of their living coral have many reefs lost in thirty years?', '[{"optionKey":"A","content":"A quarter","sortOrder":1},{"optionKey":"B","content":"Half","sortOrder":2},{"optionKey":"C","content":"All of it","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph A: many have lost half of their living coral.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000110', '2d000000-0000-4000-8000-030000000110', 1, 'What are coral fragments attached to in the nurseries?', '[{"optionKey":"A","content":"Frames made from plastic pipe or rope","sortOrder":1},{"optionKey":"B","content":"Natural rocks","sortOrder":2},{"optionKey":"C","content":"Concrete blocks","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Paragraph B: frames made from plastic pipe or rope.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000111', '2d000000-0000-4000-8000-030000000111', 1, 'Why are colonies that survived a heatwave favoured?', '[{"optionKey":"A","content":"They grow in deeper water","sortOrder":1},{"optionKey":"B","content":"They may tolerate high temperatures","sortOrder":2},{"optionKey":"C","content":"They are cheaper to collect","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: they may carry some tolerance to high temperatures.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000112', '2d000000-0000-4000-8000-030000000112', 1, 'A nursery can produce thousands of new ______ in a single year.', NULL, '{"type":"FILL","accepted":["colonies"]}'::jsonb, 1, 'Paragraph B: thousands of new colonies.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000113', '2d000000-0000-4000-8000-030000000113', 1, 'Critics say nurseries treat the symptoms rather than the ______.', NULL, '{"type":"FILL","accepted":["cause"]}'::jsonb, 1, 'Paragraph D: symptoms rather than the cause.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000114', '2d000000-0000-4000-8000-030000000114', 1, 'Supporters say restoration buys ______ while governments cut emissions.', NULL, '{"type":"FILL","accepted":["time"]}'::jsonb, 1, 'Paragraph D: restoration buys time.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000115', '2d000000-0000-4000-8000-030000000115', 1, 'The writer believes transplanted coral will survive even if the oceans keep warming.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NO"}'::jsonb, 1, 'Paragraph D: even the healthiest coral will bleach again.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000116', '2d000000-0000-4000-8000-030000000116', 1, 'The writer thinks governments should pay for coral nurseries.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'Funding of nurseries is not discussed.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000117', '2d000000-0000-4000-8000-030000000117', 1, 'The first fully electric passenger ferry began operating in 2015.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"TRUE"}'::jsonb, 1, 'Paragraph A: launched on a Norwegian fjord in 2015.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000118', '2d000000-0000-4000-8000-030000000118', 1, 'The electric ferry uses about half the energy of the diesel ferry it replaced.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"FALSE"}'::jsonb, 1, 'Paragraph B: roughly a tenth of the energy.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000119', '2d000000-0000-4000-8000-030000000119', 1, 'Passengers have complained about the lack of engine noise.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'No complaints are mentioned.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000120', '2d000000-0000-4000-8000-030000000120', 1, 'How long does it take to charge the batteries at each end of the crossing?', '[{"optionKey":"A","content":"About ten minutes","sortOrder":1},{"optionKey":"B","content":"About an hour","sortOrder":2},{"optionKey":"C","content":"A whole night","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Paragraph B: about ten minutes at each end.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000121', '2d000000-0000-4000-8000-030000000121', 1, 'Which routes suit battery ferries best?', '[{"optionKey":"A","content":"Long routes with few stops","sortOrder":1},{"optionKey":"B","content":"Short routes with frequent stops","sortOrder":2},{"optionKey":"C","content":"Routes without harbours","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: short routes with frequent stops suit it far better.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000122', '2d000000-0000-4000-8000-030000000122', 1, 'What are operators on longer crossings testing?', '[{"optionKey":"A","content":"Sailing ships","sortOrder":1},{"optionKey":"B","content":"Hybrid designs","sortOrder":2},{"optionKey":"C","content":"Larger diesel engines","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: hybrid designs combining batteries with a small engine.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000123', '2d000000-0000-4000-8000-030000000123', 1, 'a reason why many ports cannot yet charge large ferries', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"D"}'::jsonb, 1, 'Paragraph D: many harbours lack a powerful grid connection.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000124', '2d000000-0000-4000-8000-030000000124', 1, 'a comparison between the fuel use of a ferry and of cars', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Paragraph A: as much fuel as thousands of cars.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000125', '2d000000-0000-4000-8000-030000000125', 1, 'Visitor numbers have risen in several countries for ten years.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"TRUE"}'::jsonb, 1, 'Paragraph A: visitor numbers have risen for a decade.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000126', '2d000000-0000-4000-8000-030000000126', 1, 'Libraries are now used only for borrowing books.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"FALSE"}'::jsonb, 1, 'Paragraph A: no longer used only for borrowing books.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000127', '2d000000-0000-4000-8000-030000000127', 1, 'The tools lent out by the library are free to borrow.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'The price of borrowing tools is not stated.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000128', '2d000000-0000-4000-8000-030000000128', 1, 'Modern libraries often provide free ______ stations.', NULL, '{"type":"FILL","accepted":["computer"]}'::jsonb, 1, 'Paragraph B: free computer stations.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000129', '2d000000-0000-4000-8000-030000000129', 1, 'Closures hit older people and those without ______ access hardest.', NULL, '{"type":"FILL","accepted":["internet"]}'::jsonb, 1, 'Paragraph C: without internet access.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000130', '2d000000-0000-4000-8000-030000000130', 1, 'Some communities run local libraries with ______.', NULL, '{"type":"FILL","accepted":["volunteers"]}'::jsonb, 1, 'Paragraph C: running local libraries with volunteers.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000131', '2d000000-0000-4000-8000-030000000131', 1, 'a reason why people value libraries', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"D"}'::jsonb, 1, 'Paragraph D: free and neutral spaces.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000132', '2d000000-0000-4000-8000-030000000132', 1, 'a worry about public spending', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"C"}'::jsonb, 1, 'Paragraph C: councils with tight budgets closed branches.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000133', '2d000000-0000-4000-8000-030000000133', 1, 'What do sleep researchers say about teenage sleep patterns?', '[{"optionKey":"A","content":"They are mostly caused by laziness","sortOrder":1},{"optionKey":"B","content":"They are largely biological","sortOrder":2},{"optionKey":"C","content":"They are the result of homework","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph A: this pattern is largely biological.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000134', '2d000000-0000-4000-8000-030000000134', 1, 'By how much did the Seattle school delay its start?', '[{"optionKey":"A","content":"Fifty-five minutes","sortOrder":1},{"optionKey":"B","content":"Thirty-four minutes","sortOrder":2},{"optionKey":"C","content":"Two hours","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Paragraph B: from 7.50 to 8.45 a.m. is fifty-five minutes.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000135', '2d000000-0000-4000-8000-030000000135', 1, 'What do some experts fear about later starts?', '[{"optionKey":"A","content":"They will shorten the holidays","sortOrder":1},{"optionKey":"B","content":"They will disrupt sport and part-time jobs","sortOrder":2},{"optionKey":"C","content":"They will lower attendance","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: later starts may disrupt sport and part-time jobs.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000136', '2d000000-0000-4000-8000-030000000136', 1, 'During adolescence the body ______ shifts.', NULL, '{"type":"FILL","accepted":["clock"]}'::jsonb, 1, 'Paragraph A: the body clock shifts.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000137', '2d000000-0000-4000-8000-030000000137', 1, 'Students at the Seattle school slept on average ______ minutes longer each night.', NULL, '{"type":"FILL","accepted":["34","thirty-four"]}'::jsonb, 1, 'Paragraph B: 34 minutes longer.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000138', '2d000000-0000-4000-8000-030000000138', 1, 'Families can help by limiting ______ before bed.', NULL, '{"type":"FILL","accepted":["screen use"]}'::jsonb, 1, 'Paragraph C: limiting screen use before bed.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000139', '2d000000-0000-4000-8000-030000000139', 1, 'The writer believes that teenagers are simply lazy.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NO"}'::jsonb, 1, 'Paragraph A: researchers argue the pattern is largely biological.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000140', '2d000000-0000-4000-8000-030000000140', 1, 'The writer thinks all schools should start later.', '[{"optionKey":"YES","content":"YES","sortOrder":1},{"optionKey":"NO","content":"NO","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'The writer does not give a recommendation.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000141', '2d000000-0000-4000-8000-030000000141', 1, 'Britain has lost around two thirds of its traditional orchards since 1950.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"TRUE"}'::jsonb, 1, 'Paragraph A: around two thirds lost since 1950.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000142', '2d000000-0000-4000-8000-030000000142', 1, 'All surviving orchards are protected by law.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"NOT_GIVEN"}'::jsonb, 1, 'Legal protection is not mentioned.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000143', '2d000000-0000-4000-8000-030000000143', 1, 'A newly planted tree can bear a useful crop within three years.', '[{"optionKey":"TRUE","content":"TRUE","sortOrder":1},{"optionKey":"FALSE","content":"FALSE","sortOrder":2},{"optionKey":"NOT_GIVEN","content":"NOT GIVEN","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"FALSE"}'::jsonb, 1, 'Paragraph D: it may not bear a useful crop for seven years.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000144', '2d000000-0000-4000-8000-030000000144', 1, 'What do volunteers graft onto new roots?', '[{"optionKey":"A","content":"Cuttings from old varieties","sortOrder":1},{"optionKey":"B","content":"Wild apple seeds","sortOrder":2},{"optionKey":"C","content":"Branches from supermarket trees","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"A"}'::jsonb, 1, 'Paragraph B: cuttings from old varieties.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000145', '2d000000-0000-4000-8000-030000000145', 1, 'What is said to benefit the greatest number of species?', '[{"optionKey":"A","content":"Mowing every week","sortOrder":1},{"optionKey":"B","content":"Cutting the grass once a year after seeding","sortOrder":2},{"optionKey":"C","content":"Removing all wildflowers","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph C: cutting once a year, after wildflowers set seed.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000146', '2d000000-0000-4000-8000-030000000146', 1, 'Why is restoring old trees difficult?', '[{"optionKey":"A","content":"They cannot be pruned","sortOrder":1},{"optionKey":"B","content":"They are slow to recover","sortOrder":2},{"optionKey":"C","content":"They attract pests","sortOrder":3}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph D: old trees are slow to recover.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000147', '2d000000-0000-4000-8000-030000000147', 1, 'an activity that lets visitors taste rarely sold apples', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"B"}'::jsonb, 1, 'Paragraph B: autumn festivals where visitors taste rare apples.', 'PUBLISHED'),
    ('2d000000-0000-4000-8000-040000000148', '2d000000-0000-4000-8000-030000000148', 1, 'a reason why meadows under the trees matter', '[{"optionKey":"A","content":"Paragraph A","sortOrder":1},{"optionKey":"B","content":"Paragraph B","sortOrder":2},{"optionKey":"C","content":"Paragraph C","sortOrder":3},{"optionKey":"D","content":"Paragraph D","sortOrder":4}]'::jsonb, '{"type":"CHOICE","correct":"C"}'::jsonb, 1, 'Paragraph C: grasslands support bees and butterflies.', 'PUBLISHED')
